// Fingerprint inputs for runtimeVersion: { policy: 'fingerprint' }.
//
// The hash decides which builds an EAS Update reaches, so it must change
// for native changes only. A local Xcode build and CI's `eas update` hash
// different trees (different machines, installs, git state), and before
// this config they disagreed on non-native inputs, which stopped OTAs
// reaching a locally built phone:
//
// - package.json scripts (a postinstall that only generates JS) and
//   .gitignore: neither reaches the binary. Skipped below.
// - ios/ and android/: generated by prebuild (CNG) from app.json + config
//   plugins + native deps, which are hashed already. Fingerprint only
//   excludes them while git ignores them, so a tree where that check
//   didn't hold hashed the whole generated project. Ignored explicitly.
//
// Everything native still counts: native module versions (autolinking),
// app.json (minus versions), config plugins, patches/ (patch-package
// patches native code too) and the icon / splash assets.
//
// Check a change with:
//   npx expo-updates fingerprint:generate --platform ios --debug
// and see the hash move only when you expect a new build to be needed.

/** @type {import('@expo/fingerprint').Config} */
module.exports = {
  // Replaces the preset's skips rather than adding to them, so this spells
  // out 'balanced' (the default preset) plus the two additions.
  sourceSkips: [
    // balanced
    'PackageJsonAndroidAndIosScriptsIfNotContainRun',
    'ExpoConfigVersions',
    'ExpoConfigRuntimeVersionIfString',
    'EasJson',
    'Easignore',
    'AutolinkingConfigPaths',
    // ours
    'PackageJsonScriptsAll',
    'GitIgnore'
  ],
  ignorePaths: ['ios/**/*', 'android/**/*']
}
